-- RELEVÉ PAR EMPREINTES (LECTURE SEULE) — une seule requête, un seul résultat JSON, à exécuter JUSTE AVANT puis JUSTE APRÈS la migration achats_receptions_partielles.sql et à conserver.
-- Ce fichier n'est PAS une migration (aucune écriture). Il reprend les sections 1 à 7 de achats_receptions_partielles_releve.sql et les contrôles 1 à 5 de
-- achats_receptions_partielles_avant_migration.sql, condensés en empreintes MD5 : AVANT et APRÈS doivent être IDENTIQUES pour s1, s2, s3, s4, s5, s6 ;
-- seule s7 change (avant : 0 fonction, 0 colonne, 0 table, 0 déclencheur hors CUMP ; après : 10 fonctions, 11 colonnes, 2 tables, 7 déclencheurs hors CUMP, 10 déclencheurs CUMP inchangés).
-- avant_1 à avant_4 doivent valoir 0 ; avant_5_gel_actif doit valoir true après le gel (étape 1), false avant.
-- NB : s6_fonctions change aussi après migration pour reception_* UNIQUEMENT si la migration les redéfinit (elle ne le fait pas : empreintes attendues identiques).
WITH
s1 AS (SELECT s.id, s.reference, s.supplier_name, s.status AS statut_logistique, s.eta, count(i.id) AS lignes, coalesce(sum(i.quantity), 0) AS commande, coalesce(sum(i.received_quantity), 0) AS cumul_recu, count(*) FILTER (WHERE coalesce(i.received_quantity, 0) >= i.quantity) AS lignes_soldees FROM shipments s LEFT JOIN shipment_items i ON i.shipment_id = s.id GROUP BY s.id, s.reference, s.supplier_name, s.status, s.eta, s.created_at),
s2 AS (SELECT i.id, s.reference, i.product_id, i.quantity AS commande, i.received_quantity AS cumul_recu, i.unit_cost_ht, i.dlc FROM shipment_items i JOIN shipments s ON s.id = i.shipment_id),
s3 AS (SELECT r.id, r.received_at, r.supplier_name, r.stock_applied, r.notes, count(i.id) AS lignes, coalesce(sum(i.quantity), 0) AS cartons, coalesce(sum(i.quantity * i.unit_cost_ht), 0) AS valeur_ht FROM stock_receptions r LEFT JOIN stock_reception_items i ON i.reception_id = r.id GROUP BY r.id),
s4 AS (SELECT p.id, p.name, p.stock_quantity AS physique, a.reserved AS reserve, a.available AS disponible, p.prix_achat_moyen_ht FROM products p LEFT JOIN product_availability a ON a.product_id = p.id),
s5 AS (SELECT 'lignes de réception' AS objet, count(*) AS lignes, coalesce(sum(quantity), 0) AS somme, md5(coalesce(string_agg(concat_ws('|', id, reception_id, product_id, quantity, unit_cost_ht, coalesce(dlc::text, ''), created_at), ',' ORDER BY id), '')) AS empreinte FROM stock_reception_items
  UNION ALL SELECT 'journal admin_audit_logs', count(*), 0, md5(coalesce(string_agg(id::text, ',' ORDER BY created_at, id), '')) FROM admin_audit_logs),
s6a AS (SELECT t.table_name AS objet, r.role AS role, has_table_privilege(r.role, 'public.' || t.table_name, 'SELECT') AS select_, has_table_privilege(r.role, 'public.' || t.table_name, 'INSERT') AS insert_, has_table_privilege(r.role, 'public.' || t.table_name, 'UPDATE') AS update_, has_table_privilege(r.role, 'public.' || t.table_name, 'DELETE') AS delete_, c.relrowsecurity AS rls FROM (VALUES ('shipments'), ('shipment_items'), ('stock_receptions'), ('stock_reception_items'), ('products'), ('admin_audit_logs')) AS t(table_name) CROSS JOIN (VALUES ('anon'), ('authenticated'), ('service_role')) AS r(role) JOIN pg_class c ON c.relnamespace = 'public'::regnamespace AND c.relname = t.table_name),
s6b AS (SELECT p.oid::regprocedure::text AS fonction, md5(pg_get_functiondef(p.oid)) AS empreinte, has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_, has_function_privilege('authenticated', p.oid, 'EXECUTE') AS authenticated_, has_function_privilege('service_role', p.oid, 'EXECUTE') AS service_role_ FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('recalc_pump', 'reception_create', 'reception_update', 'reception_delete', 'product_adjust_stock')),
s6c AS (SELECT md5(definition) AS empreinte FROM pg_views WHERE schemaname = 'public' AND viewname = 'product_availability')
SELECT jsonb_build_object(
 'horodatage_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
 's1_commandes', (SELECT jsonb_build_object('n', count(*), 'md5', md5(string_agg(t::text, E'\n' ORDER BY t::text))) FROM s1 t),
 's2_lignes', (SELECT jsonb_build_object('n', count(*), 'cumul_total', coalesce(sum(cumul_recu),0), 'commande_total', sum(commande), 'md5', md5(string_agg(t::text, E'\n' ORDER BY t::text))) FROM s2 t),
 's3_receptions', (SELECT jsonb_build_object('n', count(*), 'cartons', sum(cartons), 'md5', md5(string_agg(t::text, E'\n' ORDER BY t::text))) FROM s3 t),
 's4_stocks', (SELECT jsonb_build_object('n', count(*), 'stock_physique_total', sum(physique), 'md5', md5(string_agg(t::text, E'\n' ORDER BY t::text))) FROM s4 t),
 's5_historiques', (SELECT jsonb_agg(to_jsonb(t) ORDER BY objet) FROM s5 t),
 's6_permissions', (SELECT jsonb_build_object('n', count(*), 'md5', md5(string_agg(t::text, E'\n' ORDER BY t::text))) FROM s6a t),
 's6_fonctions', (SELECT jsonb_agg(to_jsonb(t) ORDER BY fonction) FROM s6b t),
 's6_vue', (SELECT empreinte FROM s6c),
 's7_objets_migration', jsonb_build_object(
    'fonctions', (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname IN ('reception_commande_enregistrer','reception_commande_annuler','shipment_item_quantite_modifier','shipment_reception_etat','shipment_reception_quantites','shipment_items_proteger','shipments_proteger','stock_receptions_proteger','stock_reception_items_proteger','achats_historique_proteger')),
    'declencheurs_hors_cump', (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgrelid::regclass::text IN ('shipments','shipment_items','stock_receptions','stock_reception_items') AND tgname NOT LIKE 'trg\_cump\_%'),
    'declencheurs_cump', (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgname LIKE 'trg\_cump\_%'),
    'colonnes', (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND ((table_name='stock_receptions' AND column_name IN ('shipment_id','cle_idempotence','empreinte','bl_fournisseur','created_by','created_by_email','annulee_le','annulee_par','annulation_motif')) OR (table_name='stock_reception_items' AND column_name='shipment_item_id') OR (table_name='shipments' AND column_name='statut_avant_reception'))),
    'tables', (SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname IN ('stock_reception_items_annulees','shipment_item_quantites_historique'))),
 'avant_1_requetes_en_cours', (SELECT count(*) FROM pg_stat_activity WHERE datname = current_database() AND pid <> pg_backend_pid() AND state <> 'idle' AND query ~* '(stock_receptions|stock_reception_items|shipment_items|shipments|reception_create|reception_update|reception_delete|recalc_pump|product_adjust_stock)'),
 'avant_2_transactions_ouvertes', (SELECT count(*) FROM pg_stat_activity WHERE datname = current_database() AND pid <> pg_backend_pid() AND state IN ('idle in transaction','idle in transaction (aborted)')),
 'avant_3_verrous_ecriture', (SELECT count(*) FROM pg_locks l JOIN pg_class c ON c.oid = l.relation WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('shipments','shipment_items','stock_receptions','stock_reception_items') AND l.pid <> pg_backend_pid() AND l.mode IN ('RowExclusiveLock','ShareUpdateExclusiveLock','ShareLock','ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock')),
 'avant_4_ecritures_15min', jsonb_build_object('receptions', (SELECT count(*) FROM stock_receptions WHERE created_at > now() - interval '15 minutes'), 'commandes', (SELECT count(*) FROM shipments WHERE created_at > now() - interval '15 minutes'), 'journal_achats', (SELECT count(*) FROM admin_audit_logs WHERE created_at > now() - interval '15 minutes' AND (action LIKE 'reception.%' OR action LIKE 'transit.%' OR action LIKE 'stock.%' OR action LIKE 'achats.%'))),
 'avant_5_gel_actif', (NOT has_function_privilege('service_role','reception_create(text, date, text, boolean, jsonb, uuid)','EXECUTE') AND NOT has_function_privilege('service_role','reception_update(uuid, text, date, text, boolean, jsonb, uuid)','EXECUTE') AND NOT has_function_privilege('service_role','reception_delete(uuid)','EXECUTE'))
) AS releve;
